let data;
try {
    const lines = msg.payload.trim().split('\n');
    const lastLine = lines[lines.length - 1];
    data = JSON.parse(lastLine);
} catch (e) {
    msg.statusText = '⚠️ Parse-Fehler: ' + msg.payload;
    flow.set('letzterFehler', msg.payload);
    return [null, null, msg, null];
}

if (!data.ok) {
    msg.statusText = '⚠️ Fehler: ' + (data.error || 'unbekannt') + (data.detail ? ' (' + data.detail + ')' : '');
    flow.set('letzterFehler', data.error || 'unbekannt');
    return [null, null, msg, null];
}

const gasMsg = {
    payload: data.gas_percent,
    topic: 'rotarex/gasflasche/prozent'
};

// Der Batteriestand des Senders ist optional. Fehlt er, wird bewusst nichts
// veroeffentlicht: Ein retained MQTT-Wert null bliebe stehen und saehe aus
// wie eine leere Batterie.
const batterieDa = typeof data.battery_percent === 'number';
const battMsg = batterieDa
    ? { ...msg, payload: data.battery_percent, topic: 'rotarex/gasflasche/batterie' }
    : null;

const hinweise = [];
if (!batterieDa) {
    hinweise.push('Sender-Batterie: keine Angabe' + (data.battery_error ? ' (' + data.battery_error + ')' : ''));
}
if (data.history_error) {
    hinweise.push('⚠️ History: ' + data.history_error);
}

msg.statusText = '⛽ Gasflasche: ' + data.gas_percent + '% (roh: ' + data.gas_raw + ')'
    + (batterieDa ? ' | Sender-Batterie: ' + data.battery_percent + '%' : '')
    + (hinweise.length ? ' | ' + hinweise.join(' | ') : '');

flow.set('letzterGasstand', data.gas_percent);
flow.set('letzteMessung', new Date().toISOString());
flow.set('letzterFehler', data.history_error || null);

// Kapazitaet in m3 und FluidType (8 = LPG) hier anpassen. Achtung:
// Diese Werte werden bei JEDEM Abruf neu gesetzt und ueberschreiben
// damit, was im GX unter Setup eingetragen ist. Wer die Kapazitaet
// lieber dort pflegt, nimmt '/FluidType' und '/Capacity' hier raus.
const tankMsg = {
    payload: {
        '/Level': data.gas_percent,
        '/FluidType': 8,
        '/Capacity': 0.021,
        '/Status': 0
    }
};

return [gasMsg, battMsg, msg, tankMsg];
